17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.time.LocalDate;
20	import java.util.Locale;
21	import java.util.Set;
22	import java.util.regex.Pattern;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
30	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
31	import org.springframework.samples.petclinic.service.ClinicService;
32	import org.springframework.samples.petclinic.util.HashUtils;
33	import org.springframework.samples.petclinic.util.IdentityUtils;
34	import org.springframework.stereotype.Component;
35	import org.springframework.web.util.UriComponentsBuilder;
36	
37	/**
38	 * Owns the owner-creation concern: the single place that turns a submitted
39	 * {@link OwnerFieldsDto} into a validated, normalized, enriched and persisted {@link Owner},
40	 * and reports the create outcome as the HTTP response the endpoint returns.
41	 *
42	 * <p>Keeping the whole create pipeline here means every rule that fires on create — the
43	 * registration-date and business-day handling, the per-day and per-city quotas, the
44	 * address/telephone/email/postcode normalization and validation, the household, duplicate
45	 * and soft-match identity rules, and the derived member id and namesake count — reads the
46	 * one owner this class builds, in the one order it applies
47	 * them, so they can never drift apart. The controller is left holding only the endpoint's
48	 * HTTP boundary.
49	 */
50	@Component
51	public class OwnerRegistrar {
52	
53	    /** Minimal syntactic check for an email address: a non-empty local part, a single
54	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
55	    private static final Pattern EMAIL_PATTERN =
56	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
57	
58	    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
59	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
60	
61	    /** Disposable email domains that are rejected: an owner whose email domain matches one of
62	     *  these (case-insensitively) is refused with 400. */
63	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
64	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final TelephoneNormalizer telephoneNormalizer;
71	
72	    private final AddressNormalizer addressNormalizer;
73	
74	    private final CityRegionResolver cityRegionResolver;
75	
76	    private final HouseholdResolver householdResolver;
77	
78	    private final OwnerAuditor ownerAuditor;
79	
80	    /**
81	     * Remembers, per {@code Idempotency-Key}, the id of the owner that key's create originally
82	     * produced, so a later create carrying the same key returns that same owner instead of
83	     * creating a duplicate. The registrar is a singleton, so this store outlives a single
84	     * request; entries are keyed by the client-supplied key, which is expected to be unique
85	     * per logical create.
86	     */
87	    private final java.util.concurrent.ConcurrentHashMap<String, Integer> idempotencyKeys =
88	        new java.util.concurrent.ConcurrentHashMap<>();
89	
90	    public OwnerRegistrar(ClinicService clinicService,
91	                          OwnerMapper ownerMapper,
92	                          TelephoneNormalizer telephoneNormalizer,
93	                          AddressNormalizer addressNormalizer,
94	                          CityRegionResolver cityRegionResolver,
95	                          HouseholdResolver householdResolver,
96	                          OwnerAuditor ownerAuditor) {
97	        this.clinicService = clinicService;
98	        this.ownerMapper = ownerMapper;
99	        this.telephoneNormalizer = telephoneNormalizer;
100	        this.addressNormalizer = addressNormalizer;
101	        this.cityRegionResolver = cityRegionResolver;
102	        this.householdResolver = householdResolver;
103	        this.ownerAuditor = ownerAuditor;
104	    }
105	
106	    /**
107	     * Validate, normalize, enrich and persist a new owner from the submitted fields, and
108	     * report the outcome as the response the create endpoint returns: {@code 201 Created}
109	     * (with a {@code Location} header and the created owner) on success, or the appropriate
110	     * rejection status ({@code 400}, {@code 409} or {@code 429}) when a create rule refuses
111	     * the request. No owner is persisted unless every rule passes.
112	     *
113	     * @param ownerFieldsDto the submitted owner fields
114	     * @return the create outcome as an HTTP response
115	     */
116	    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto) {
117	        return register(ownerFieldsDto, null);
118	    }
119	
120	    /**
121	     * As {@link #register(OwnerFieldsDto)}, but honouring an optional {@code Idempotency-Key}.
122	     * When {@code idempotencyKey} is non-blank and a create with that key has already succeeded,
123	     * the owner it originally produced is returned with {@code 200 OK} instead of creating a
124	     * duplicate. Otherwise the normal create pipeline runs and, on success, the key is recorded
125	     * against the created owner so a later repeat resolves to the same owner.
126	     *
127	     * @param ownerFieldsDto the submitted owner fields
128	     * @param idempotencyKey the request's {@code Idempotency-Key} header, or {@code null} when absent
129	     * @return the create outcome as an HTTP response
130	     */
131	    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
132	        String key = (idempotencyKey == null || idempotencyKey.isBlank()) ? null : idempotencyKey.trim();
133	        if (key != null) {
134	            Integer existingId = idempotencyKeys.get(key);
135	            if (existingId != null) {
136	                Owner original = this.clinicService.findOwnerById(existingId);
137	                if (original != null) {
138	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(original), HttpStatus.OK);
139	                }
140	                // The originally created owner is gone; forget the stale key and create afresh.
141	                idempotencyKeys.remove(key);
142	            }
143	        }
144	        HttpHeaders headers = new HttpHeaders();
145	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
146	        if (owner.getRegistrationDate() == null) {
147	            owner.setRegistrationDate(LocalDate.now());
148	        }
149	        // A supplied registration date may not be later than the server's current date.
150	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
151	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
152	        }
153	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
154	        LocalDate registrationDate = owner.getRegistrationDate();
155	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
156	            .map(Owner::getRegistrationDate)
157	            .filter(registrationDate::equals)
158	            .count();
159	        if (ownersCreatedThatDay >= 100) {
160	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
161	        }
162	        String address = normalizedAddress(owner);
163	        if (address == null) {
164	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
165	        }
166	        owner.setAddress(address);
167	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
168	        if (telephone == null) {
169	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
170	        }
171	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
172	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
173	        }
174	        owner.setTelephone(telephone);
175	        String email = owner.getEmail();
176	        if (email != null) {
177	            email = email.trim();
178	            if (!EMAIL_PATTERN.matcher(email).matches()) {
179	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
180	            }
181	            String domain = email.substring(email.indexOf('@') + 1).toLowerCase(Locale.ROOT);
182	            if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
183	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
184	            }
185	            owner.setEmail(email.toLowerCase(Locale.ROOT));
186	        }
187	        // A postcode is optional, but when supplied it must be four digits and valid for the
188	        // owner's city per the fixed region table; a city with no known region accepts any
189	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
190	        String postcode = owner.getPostcode();
191	        if (postcode != null) {
192	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
193	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
194	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
195	            }
196	        }
197	        // The owner's telephone and email are now in their canonical, stored form.
198	        // The household id is deterministic: owners with the same normalized last name and
199	        // postcode share it automatically. Assign it unconditionally so the membership-level
200	        // ceiling can key off it; it no longer participates in duplicate detection, which now
201	        // rests solely on the identity key below.
202	        owner.setHouseholdId(householdResolver.householdId(owner));
203	        // Duplicate detection is the single identity key: a candidate is rejected only when its
204	        // whole identityKey (normalized telephone, lower-cased email and soundex of the last name)
205	        // collides with a non-deleted owner's. Two people sharing a household with different
206	        // telephones therefore derive different keys and are both admitted; the second is instead
207	        // flagged as a possible duplicate by the soft-match rule below.
208	        if (isDuplicateOwner(owner)) {
209	            return new ResponseEntity<>(HttpStatus.CONFLICT);
210	        }
211	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
212	        long ownersInCity = this.clinicService.findAllOwners().stream()
213	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
214	            .count();
215	        if (ownersInCity >= 50) {
216	            return new ResponseEntity<>(HttpStatus.CONFLICT);
217	        }
218	        // Approaching-capacity warning: the city already holds 40-49 owners (the hard limit is 50,
219	        // rejected above). ownersInCity counts the existing owners the candidate is joining.
220	        owner.setCapacityWarning(ownersInCity >= 40 && ownersInCity < 50);
221	        owner.setMemberId(memberId(owner));
222	        owner.setNamesakeCount(namesakeCount(owner));
223	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
224	        // Soft-match: the candidate has already cleared the hard-duplicate check, but its
225	        // identityKey may still differ from an existing owner's while their last names sound alike
226	        // (equal soundex) and their postcodes match — a likely re-registration of the same person
227	        // under a different telephone or email. When it does, it is created but flagged as a
228	        // possible duplicate of that existing owner; otherwise the flag is false and no reference
229	        // is recorded.
230	        Integer possibleDuplicateOf = possibleDuplicateOf(owner);
231	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
232	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
233	        this.clinicService.saveOwner(owner);
234	        if (key != null) {
235	            idempotencyKeys.put(key, owner.getId());
236	        }
237	        ownerAuditor.ownerCreated(owner, ownerMapper.membershipLevel(owner));
238	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
239	        headers.setLocation(UriComponentsBuilder.newInstance()
240	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
241	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
242	    }
243	
244	    /**
245	     * The owner's postal address in the single canonical form under which it is stored, or
246	     * {@code null} when the owner supplies no usable address. An owner may supply its address
247	     * in EITHER form: the structured {@code addressLine1} (with an optional {@code addressLine2})
248	     * is preferred, and the flat {@code address} remains accepted for backward compatibility.
249	     *
250	     * <p>Normalization by {@link AddressNormalizer} is applied to whichever fields are supplied.
251	     * When a non-blank {@code addressLine1} is present the owner's structured fields are replaced
252	     * with their normalized values (a blank or absent {@code addressLine2} is cleared to
253	     * {@code null}) and the returned address is composed as the normalized {@code addressLine1},
254	     * with a single space and the normalized {@code addressLine2} appended when present. Otherwise
255	     * the flat {@code address} is normalized and the structured fields are cleared. A blank result
256	     * (no usable address in either form) has no canonical form and is reported as {@code null} so
257	     * the caller can reject the request with 400.
258	     *
259	     * <p>This is the single point at which an owner's address is resolved and normalized on
260	     * create, so every rule keyed on the stored address reads the one value produced here.
261	     *
262	     * @param owner the owner about to be created
263	     * @return the canonical stored address, or {@code null} when the owner supplies none
264	     */
265	    private String normalizedAddress(Owner owner) {
266	        String rawLine1 = owner.getAddressLine1();
267	        if (rawLine1 != null && !rawLine1.isBlank()) {
268	            String line1 = addressNormalizer.normalize(rawLine1);
269	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
270	            owner.setAddressLine1(line1);
271	            owner.setAddressLine2(line2.isBlank() ? null : line2);
272	            return line2.isBlank() ? line1 : line1 + " " + line2;
273	        }
274	        owner.setAddressLine1(null);
275	        owner.setAddressLine2(null);
276	        String address = addressNormalizer.normalize(owner.getAddress());
277	        return address.isBlank() ? null : address;
278	    }
279	
280	    /**
281	     * Whether {@code candidate} collides with an already-registered owner under the single
282	     * identity rule enforced on create. This is the one point at which a new owner is
283	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
284	     * derived {@link OwnerMapper#identityKey identityKey} — the SHA-256 hex over the normalized
285	     * telephone, the lower-cased email (or an empty string when absent) and the soundex of the
286	     * last name, joined by '|'. The candidate clashes only when its WHOLE identityKey equals an
287	     * existing owner's; because the telephone is part of the key, two people sharing a household
288	     * (a like-sounding last name and postcode) with different telephones have different
289	     * identityKeys and are both allowed.
290	     *
291	     * <p>The candidate arrives with its telephone and email already normalized, and each existing
292	     * owner is stored in the same canonical form, so an identityKey match means the two owners are
293	     * genuinely the same identity.
294	     *
295	     * @param candidate the fully-normalized owner about to be created
296	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
297	     */
298	    private boolean isDuplicateOwner(Owner candidate) {
299	        String identityKey = OwnerMapper.identityKey(candidate);
300	        return this.clinicService.findAllOwners().stream()
301	            .filter(existing -> !existing.isDeleted())
302	            .map(OwnerMapper::identityKey)
303	            .anyMatch(identityKey::equals);
304	    }
305	
306	    /**
307	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
308	     * {@code null} when there is none. A soft match is an owner whose whole identityKey differs
309	     * from the candidate's (so it is not a hard duplicate) yet whose last name sounds alike (equal
310	     * {@link IdentityUtils#soundex soundex}) and whose postcode matches — a likely re-registration
311	     * of the same person under a different telephone or email. Both must supply a postcode for a
312	     * match to be possible; when several existing owners qualify the lowest id is returned so the
313	     * result is deterministic.
314	     *
315	     * @param candidate the fully-normalized owner about to be created
316	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
317	     */
318	    private Integer possibleDuplicateOf(Owner candidate) {
319	        String postcode = candidate.getPostcode();
320	        if (postcode == null || postcode.isBlank()) {
321	            return null;
322	        }
323	        String identityKey = OwnerMapper.identityKey(candidate);
324	        String lastNameSoundex = IdentityUtils.soundex(candidate.getLastName());
325	        return this.clinicService.findAllOwners().stream()
326	            .filter(existing -> !existing.isDeleted()
327	                && !identityKey.equals(OwnerMapper.identityKey(existing))
328	                && IdentityUtils.soundex(existing.getLastName()).equals(lastNameSoundex)
329	                && postcode.equals(existing.getPostcode()))
330	            .map(Owner::getId)
331	            .filter(java.util.Objects::nonNull)
332	            .min(Integer::compareTo)
333	            .orElse(null);
334	    }
335	
336	    /**
337	     * Build the member id assigned to {@code owner} on create, formatted
338	     * {@code '<REGION><FY><HASH8><CHK>'}: REGION is the region code derived from the owner's
339	     * postcode (falling back to the city) via {@link CityRegionResolver}, FY is the two-digit
340	     * fiscal year of the (business-day-adjusted) registrationDate (the fiscal year starts on
341	     * 1 July), HASH8 is the first eight upper-case hex characters of the SHA-256 digest of the
342	     * normalized telephone concatenated with the last name (the same HASH8 used by the
343	     * region-and-hash identity), and CHK is a single Luhn check digit computed over the digits
344	     * of {@code '<REGION><FY><HASH8>'} (e.g. 'NSW261A2B3C4D5').
345	     *
346	     * <p>When the computed id collides with an already-registered owner's memberId it is
347	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
348	     * makes it unique (e.g. 'NSW261A2B3C4D5-2'), and the unique id is returned.
349	     */
350	    private String memberId(Owner owner) {
351	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
352	        String fy = String.format("%02d", OwnerMapper.fiscalYear(owner.getRegistrationDate()) % 100);
353	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
354	        String core = region + fy + hash8;
355	        String base = core + OwnerMapper.luhn(core);
356	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
357	            .map(Owner::getMemberId)
358	            .filter(java.util.Objects::nonNull)
359	            .collect(java.util.stream.Collectors.toSet());
360	        return disambiguate(base, existing);
361	    }
362	
363	    /**
364	     * Make {@code base} unique among the {@code existing} identity codes: return it unchanged when
365	     * it is free, otherwise append {@code '-<n>'} with the smallest {@code n} of 2 or more that is
366	     * not already taken (e.g. 'NSW-1A2B3C4D-2'). This is the single de-duplication step an assigned
367	     * identity code passes through, so a collision is broken the one way wherever a code is built.
368	     */
369	    private static String disambiguate(String base, java.util.Set<String> existing) {
370	        if (!existing.contains(base)) {
371	            return base;
372	        }
373	        int n = 2;
374	        while (existing.contains(base + "-" + n)) {
375	            n++;
376	        }
377	        return base + "-" + n;
378	    }
379	
380	    /**
381	     * The number of existing owners that share {@code owner}'s firstName and lastName,
382	     * compared case-insensitively. The candidate is not yet stored at the point this is
383	     * assigned, so it does not count itself. This is the value stored as the owner's
384	     * namesakeCount on create.
385	     */
386	    private int namesakeCount(Owner owner) {
387	        return (int) this.clinicService.findAllOwners().stream()
388	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
389	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
390	            .count();
391	    }
392	
393	    /** Fixed list of public holidays that a registration date must roll past. */
394	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
395	        LocalDate.of(2026, 1, 1),
396	        LocalDate.of(2026, 1, 26),
397	        LocalDate.of(2026, 4, 25),
398	        LocalDate.of(2026, 12, 25),
399	        LocalDate.of(2026, 12, 28));
400	
401	    /**
402	     * Roll a registration date forward to the next business day: a Saturday, Sunday
403	     * or listed public holiday advances one day at a time until it lands on a weekday
404	     * that is not a public holiday. A plain weekday is returned unchanged.
405	     */
406	    private static LocalDate toBusinessDay(LocalDate date) {
407	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
408	            date = date.plusDays(1);
409	        }
410	        return date;
411	    }
412	
413	    private static boolean isWeekend(LocalDate date) {
414	        return switch (date.getDayOfWeek()) {
415	            case SATURDAY, SUNDAY -> true;
416	            default -> false;
417	        };
418	    }
419	}
